        for row in panel:
            for value in row:
                counts[value] = counts.get(value, 0) + 1
        return counts

    lc, rc = frequencies(left), frequencies(right)
    left_bg = max(lc, key=lc.get)
    right_bg = max(rc, key=rc.get)

    if left_bg == right_bg:
        return [
            [2 if left[r][c] != left_bg or right[r][c] != right_bg else 3
             for c in range(n)]
            for r in range(h)
        ]

